        self.figure_format_combo.addItems(["png", "jpg", "jpeg", "tif", "tiff"])
        self.figure_format_combo.currentTextChanged.connect(self.on_figure_options_changed)
        row.addWidget(self.figure_format_combo)

        row.addWidget(QLabel("DPI:"))
